module vga_controller(
    input clk_i, rst_i, 
    output hsync_o, vsync_o,
    output disp_active,
    output[10:0] xcol_o, yrow_o 
    );

    localparam H_DISP = 640;    
    localparam H_BPORCH = 48;   
    localparam H_FPORCH = 16;   
    localparam H_SYNC = 96;     
    localparam H_FRAME = 800;   
    localparam V_DISP = 480;    
    localparam V_BPORCH = 33;   
    localparam V_FPORCH = 10;   
    localparam V_SYNC = 2;     
    localparam V_FRAME = 525;   

reg[10:0] col_cnt, row_cnt = 0;
reg hsync, vsync = 0; 
reg sync_p = 0;

always @(posedge clk_i)
begin
    if(rst_i) begin
        col_cnt <= 0;
        row_cnt <= 0;
    end
    else begin
        if (col_cnt == H_FRAME-1) begin
            col_cnt <= 0;
            if(row_cnt == V_FRAME-1) begin
                row_cnt <= 0;
            end
            else begin            
                row_cnt <= row_cnt + 1;
            end       
        end
        else begin    
            col_cnt <= col_cnt + 1;
        end   
    end   
end  

always @(posedge clk_i) 
begin
    if (rst_i) begin
        hsync <= ~ sync_p;
    end
    else begin
        if ((col_cnt < (H_DISP + H_FPORCH)) ||
            (col_cnt > (H_FRAME - H_BPORCH-1))) begin
            hsync <= ~sync_p;
        end    
        else begin
            hsync <= sync_p;
        end                                              
    end
end 

always @(posedge clk_i) 
begin
    if (rst_i) begin
        vsync <= ~sync_p;
    end
    else begin   
        if ((row_cnt < (V_DISP + V_BPORCH)) ||
            (row_cnt > (V_FRAME - V_FPORCH -1))) begin
            vsync <= ~sync_p;
        end    
        else begin
            vsync <= sync_p;
        end                                                    
    end
end    

assign disp_active = ((col_cnt < H_DISP) && (row_cnt < V_DISP)) ? 1 : 0; 
assign hsync_o = hsync;
assign vsync_o = vsync;   
assign xcol_o = col_cnt;
assign yrow_o = row_cnt;

endmodule

