`timescale 1ns / 1ps
module testbench;

// Parameters
localparam H_FRAME = 800;
localparam V_FRAME = 525;

// Inputs
reg clk_i;
reg rst_i;

// Outputs
wire hsync_o;
wire vsync_o;
wire disp_active;
wire [10:0] xcol_o;
wire [10:0] yrow_o;

// Instantiate the Unit Under Test (UUT)
vga_controller uut (
    .clk_i(clk_i), 
    .rst_i(rst_i), 
    .hsync_o(hsync_o), 
    .vsync_o(vsync_o), 
    .disp_active(disp_active), 
    .xcol_o(xcol_o), 
    .yrow_o(yrow_o)
);

// Clock generation
always #5 clk_i = ~clk_i;

integer error_count = 0;

initial begin
    // Initialize Inputs
    clk_i = 0;
    rst_i = 0;

    // Wait 100 ns for global reset to finish
    #100;

    // Test Case 1: Normal operation after reset
    rst_i = 1;
    #10;
    rst_i = 0;
    #10;
    $display("===========TestCases===========");
    $display("Test Case 1: Normal operation after reset");
    if (xcol_o !== 1 || yrow_o !== 0 || hsync_o !== 1 || vsync_o !== 1) begin
        $display("Mismatch: Expected xcol_o = 1, yrow_o = 0, hsync_o = 1, vsync_o = 1");
        error_count = error_count + 1;
    end
    $display("Actual: xcol_o = %d, yrow_o = %d, hsync_o = %b, vsync_o = %b", xcol_o, yrow_o, hsync_o, vsync_o);

    // Test Case 2: Check horizontal sync pulse
    #((H_FRAME - 1) * 10); // Wait for one full horizontal frame
    $display("Test Case 2: Horizontal sync pulse");
    if (hsync_o !== 1) begin
        $display("Mismatch: Expected hsync_o = 1");
        error_count = error_count + 1;
    end
    $display("Actual: hsync_o = %b", hsync_o);

    // Test Case 3: Check vertical sync pulse
    #((V_FRAME - 1) * H_FRAME * 10); // Wait for one full vertical frame
    $display("Test Case 3: Vertical sync pulse");
    if (vsync_o !== 1) begin
        $display("Mismatch: Expected vsync_o = 1");
        error_count = error_count + 1;
    end
    $display("Actual: vsync_o = %b", vsync_o);

    // Test Case 4: Display active region
    #10;
    $display("Test Case 4: Display active region");
    if (disp_active !== 1) begin
        $display("Mismatch: Expected disp_active = 1");
        error_count = error_count + 1;
    end
    $display("Actual: disp_active = %b", disp_active);

    // Test Case 5: Edge case at the end of frame
    #((H_FRAME - 1) * 10);
    $display("Test Case 5: Edge case at the end of frame");
    if (xcol_o !== 0 || yrow_o !== 1) begin
        $display("Mismatch: Expected xcol_o = 0, yrow_o = 1");
        error_count = error_count + 1;
    end
    $display("Actual: xcol_o = %d, yrow_o = %d", xcol_o, yrow_o);

    $display("===========End===========");

    // Be sure to report the final test score
    if (error_count == 0) begin
        $display("===========Your Design Passed===========");
    end else begin
        $display("===========Test completed with %d failures===========", error_count);
    end

    // Must finish simulation
    $finish;
end

endmodule
